.pks1-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pks1-root,.pks1-root *,.pks1-root *::before,.pks1-root *::after{box-sizing:border-box}
.pks1-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pks1-root img{display:block;border:0;max-width:none}
.pks1-root [hidden]{display:none!important}
.pks1-root .n1_10146{align-content:stretch;display:flex;gap:7px;align-items:center;position:relative;flex-shrink:0}
.pks1-root .n1_10147{align-content:stretch;display:flex;gap:7px;align-items:center;position:relative;flex-shrink:0}
.pks1-root .n1_10148{position:relative;flex-shrink:0;width:3.885px;height:3.885px}
.pks1-root .x143{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.pks1-root .n1_10149{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:14px;font-style:normal;position:relative;flex-shrink:0;font-size:0px;color:var(--wa-text, #fff);white-space:nowrap;width:48px}
.pks1-root .x144{font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;line-height:normal;color:var(--wa-point, #14e6db);font-size:12px}
.pks1-root .x145{line-height:normal;font-size:12px}
.pks1-root .n1_10149{height:14px}
.pks1-root .n1_10149>span{vertical-align:top}
.pks1-root .n1_10150{align-content:stretch;display:flex;align-items:center;position:relative;flex-shrink:0;width:185px}
.pks1-root .n1_10151{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:14px;font-style:normal;position:relative;flex-shrink:0;font-size:12px;color:var(--wa-text, #fff);white-space:nowrap;width:171px}
.pks1-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.pks1-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.pks1-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.pks1-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.pks1-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.pks1-root[data-theme="light"] .n1_10149{color:var(--wa-text, #10231d)}
.pks1-root[data-theme="light"] .x144{color:var(--wa-point, #0ea098)}
